using System.Net;
using System.Net.Http.Json;

namespace sv_1d7bc4b97ffe4be1b6bd7d75aa5619a5.Client.Services;

public sealed class WasmShipmentService : IShipmentService
{
    private readonly HttpClient _http;

    public WasmShipmentService(HttpClient http)
    {
        _http = http;
    }

    public async Task<ShipmentDetails> GetShipmentAsync(string trackingNumber, CancellationToken ct)
    {
        var response = await _http.GetAsync($"api/shipments/{Uri.EscapeDataString(trackingNumber)}", ct);

        if (response.StatusCode == HttpStatusCode.NotFound)
        {
            throw new KeyNotFoundException($"Shipment with tracking number '{trackingNumber}' was not found.");
        }

        response.EnsureSuccessStatusCode();

        var shipment = await response.Content.ReadFromJsonAsync<ShipmentDetails>(ct)
            ?? throw new InvalidOperationException("Received null response from server.");

        return shipment;
    }
}

